//! Generate `rules/kani/src/generated/cond_irs.rs` from the inventory of
//! guard condition strings.
//!
//! Run from the worktree:
//! ```sh
//! cargo run -p rules-cond --features lower --example gen_cond_ir
//! ```
//!
//! The output is checked in; `tests/cond_ir_consistency.rs` re-lowers every
//! inventory string and asserts it matches the embedded form, so the
//! generated file cannot drift.

use rules_cond::lower::{lower_src, OwnedProgram};
use rules_cond_ir::nodes::{Kind, Node};

fn main() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .unwrap();
    let mut guards = rules_cond::lower::inventory_guards(&root.join("cards"));
    for d in ["skills", "tiles", "events", "fixtures"] {
        for g in rules_cond::lower::inventory_guards(&root.join(d)) {
            guards.push(g);
        }
    }
    guards.sort();
    guards.dedup();
    let mut out = String::new();
    out.push_str("//! GENERATED by `cargo run -p rules-cond --features lower --example gen_cond_ir`.\n");
    out.push_str("//! Do not edit by hand. Consistency-checked by\n");
    out.push_str("//! `rules/cond/tests/cond_ir_consistency.rs`.\n");
    out.push_str("//!\n");
    out.push_str("//! Single source of truth: the CEL condition string on each `On::*`\n");
    out.push_str("//! entry. This file is the Kani-side IR of those strings.\n\n");
    out.push_str("#![allow(dead_code)]\n\n");
    out.push_str("use rules_cond_ir::nodes::{Kind, Node};\n");
    out.push_str("use rules_cond_ir::Program;\n\n");
    out.push_str("/// Lowered guard programs, one per distinct inventory condition.\n");
    out.push_str("/// `SRC` is the CEL string; `PROGRAM` is its IR.\n");
    out.push_str("pub struct GuardIr {\n    pub src: &'static str,\n    pub program: Program,\n}\n\n");

    for (i, src) in guards.iter().enumerate() {
        let prog = match lower_src(src) {
            Ok(p) => p,
            Err(e) => {
                eprintln!("skip (unlowerable): {src:?}: {e}");
                continue;
            }
        };
        let name = guard_ident(i, src);
        out.push_str(&format!("/// `{src}`\n"));
        out.push_str(&format!("pub static {name}_NODES: &[Node] = &[\n"));
        for n in &prog.nodes {
            out.push_str(&format!("    {},\n", node_lit(n)));
        }
        out.push_str("];\n");
        out.push_str(&format!(
            "pub static {name}: GuardIr = GuardIr {{\n    src: \"{}\",\n    program: Program {{ nodes: {name}_NODES, root: {} }},\n}};\n\n",
            src.replace('\\', "\\\\").replace('"', "\\\""),
            prog.root
        ));
    }

    out.push_str("/// Every generated guard, for the consistency check.\n");
    out.push_str("pub static ALL: &[&GuardIr] = &[\n");
    for (i, src) in guards.iter().enumerate() {
        if lower_src(src).is_err() {
            continue;
        }
        let name = guard_ident(i, src);
        out.push_str(&format!("    &{name},\n"));
    }
    out.push_str("];\n");

    let dest = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .unwrap()
        .join("kani/src/generated/cond_irs.rs");
    std::fs::create_dir_all(dest.parent().unwrap()).unwrap();
    std::fs::write(&dest, out).unwrap();
    eprintln!("wrote {}", dest.display());
}

fn guard_ident(i: usize, src: &str) -> String {
    // Stable name from a short hash of the source.
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in src.as_bytes() {
        h ^= *b as u64;
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    format!("G_{:04x}_{:016x}", i, h)
}

fn node_lit(n: &Node) -> String {
    let k = match n.kind {
        Kind::ConstInt => "Kind::ConstInt",
        Kind::ConstBool => "Kind::ConstBool",
        Kind::ConstNull => "Kind::ConstNull",
        Kind::Var => "Kind::Var",
        Kind::Neg => "Kind::Neg",
        Kind::Not => "Kind::Not",
        Kind::And => "Kind::And",
        Kind::Or => "Kind::Or",
        Kind::Tern => "Kind::Tern",
        Kind::Add => "Kind::Add",
        Kind::Sub => "Kind::Sub",
        Kind::Mul => "Kind::Mul",
        Kind::Div => "Kind::Div",
        Kind::Rem => "Kind::Rem",
        Kind::Eq => "Kind::Eq",
        Kind::Ne => "Kind::Ne",
        Kind::Lt => "Kind::Lt",
        Kind::Le => "Kind::Le",
        Kind::Gt => "Kind::Gt",
        Kind::Ge => "Kind::Ge",
        Kind::In => "Kind::In",
        Kind::Size => "Kind::Size",
        Kind::List => "Kind::List",
        Kind::Call => "Kind::Call",
    };
    format!(
        "Node {{ kind: {k}, payload: {}, a: {}, b: {}, c: {} }}",
        n.payload, n.a, n.b, n.c
    )
}

fn collect_guards() -> Vec<String> {
    let mut out = Vec::new();
    let roots = [
        concat!(env!("CARGO_MANIFEST_DIR"), "/../cards"),
        concat!(env!("CARGO_MANIFEST_DIR"), "/../skills"),
        concat!(env!("CARGO_MANIFEST_DIR"), "/../tiles"),
        concat!(env!("CARGO_MANIFEST_DIR"), "/../events"),
        concat!(env!("CARGO_MANIFEST_DIR"), "/../fixtures"),
    ];
    for root in roots {
        collect_dir(std::path::Path::new(root), &mut out);
    }
    // Also the shared sugar constant.
    out.push("actor == owner".to_string());
    out
}

fn collect_dir(dir: &std::path::Path, out: &mut Vec<String>) {
    let Ok(rd) = std::fs::read_dir(dir) else {
        return;
    };
    for e in rd.flatten() {
        let p = e.path();
        if p.is_dir() {
            collect_dir(&p, out);
            continue;
        }
        if p.extension().and_then(|s| s.to_str()) != Some("rs") {
            continue;
        }
        let Ok(text) = std::fs::read_to_string(&p) else {
            continue;
        };
        for kind in [
            "Play",
            "Hook",
            "Counteract",
            "Gate",
            "RollPlan",
            "AtEnd",
            "Settle",
            "Message",
        ] {
            let pat = format!("On::{kind}(");
            let mut rest = text.as_str();
            while let Some(i) = rest.find(&pat) {
                rest = &rest[i + pat.len()..];
                if let Some(s) = first_string_literal(rest) {
                    if !s.is_empty() {
                        out.push(s);
                    }
                }
            }
        }
    }
}

fn first_string_literal(s: &str) -> Option<String> {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && bytes[i] != b'"' {
        if bytes[i] == b';' {
            return None;
        }
        i += 1;
    }
    if i >= bytes.len() {
        return None;
    }
    i += 1;
    let start = i;
    while i < bytes.len() && bytes[i] != b'"' {
        if bytes[i] == b'\\' {
            i += 1;
        }
        i += 1;
    }
    if i > bytes.len() {
        return None;
    }
    Some(s[start..i].to_string())
}